"""Imprimibles y planificación NM2 desde el catálogo de aula, sin claves públicas."""
from pathlib import Path
import json,re,html
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'paes/nm2/materiales';OUT.mkdir(exist_ok=True)
D=json.loads((ROOT/'paes/nm2/data/clases.json').read_text(encoding='utf-8'))
V=json.loads((ROOT/'paes/nm2/data/visuales.json').read_text(encoding='utf-8'))['lessons']
E=lambda s:html.escape(str(s))
template=(ROOT/'referencias/formato-institucional/plantilla-guia.html').read_text(encoding='utf-8')
basecss=re.search(r'<style>(.*?)</style>',template,re.S)[1].replace("../../assets/","../../../assets/")
header=re.search(r'  <div class="membrete-banner">.*?<section class="instructions">',template,re.S)[0].rsplit('<section',1)[0].replace('../../estudiantes/','../../../estudiantes/').replace('[Asignatura]','Lengua y Literatura').replace('[Nivel]','2.º medio HC')
basecss='\n'.join(line.rstrip() for line in basecss.splitlines())+'\n'
css=basecss+'''
.sheet{height:276mm;position:relative;break-after:page;padding-bottom:14mm}.sheet:last-child{break-after:auto}.sheet>.footer{position:absolute;bottom:0;left:0;right:0}.sheet h2{font:700 17px/1.3 Inter,sans-serif;margin:8px 0 12px}.sheet h3{font:700 13px/1.4 Inter,sans-serif;margin:8px 0}.content{font:13px/1.5 Inter,sans-serif}.content p{margin:9px 0}.objective{border:1px solid #555;padding:10px;margin:10px 0}.card{border:1px solid #777;padding:10px 12px;margin:12px 0;break-inside:avoid}.card p{font-size:13px;margin:6px 0}.card small{font-size:9px}.example{border-left:2px solid #555;padding-left:10px}.reading{font:13px/1.6 Merriweather,Georgia,serif;margin:10px 0 15px}.reading p{white-space:pre-line;margin:8px 0}.source{font:10px/1.4 Inter,sans-serif!important;margin:7px 0!important}.question{margin:12px 0 16px;break-inside:avoid}.question p{font:13px/1.4 Inter,sans-serif;margin:4px 0}.question .option{padding-left:15px}.line{height:7mm;border-bottom:1px solid #999}.blank{margin:8px 0 20px}.overview{width:100%;height:240mm;object-fit:contain}.model{border-left:3px solid #333;padding:8px 14px;margin:12px 0}.print-tools{padding:12px}.rules{border:1px solid #777;padding:8px 12px;margin:12px 0}.rules p{font-size:12px}.info-table .objective-value{font-size:9.5px}.plan{font:14px/1.5 Inter,Arial,sans-serif;max-width:1100px;margin:30px auto;background:#fff;padding:25px;color:#17383b}.plan h1{font-size:29px}.plan h2{font-size:22px;margin-top:25px}.plan h3{font-size:17px;margin-top:20px}.plan table{width:100%;border-collapse:collapse;margin:15px 0}.plan th,.plan td{border:1px solid #7e9592;padding:10px;text-align:left;vertical-align:top}.plan p{margin:12px 0}.roadmap{break-after:page}.plan .roadmap h1{font-size:25px}.plan .roadmap table{font-size:12px}.plan a{color:#145d60}@media print{.print-tools{display:none}.plan{margin:0;padding:0;max-width:none}.roadmap{height:276mm}body{padding:0}.content{color:#111}}
'''
def lines(n):return '<div class="blank">'+''.join('<div class="line"></div>' for _ in range(n))+'</div>'
def qhtml(q):return '<div class="question"><p><b>'+str(int(q['id'][1:]))+'. '+E(q['text'])+'</b></p>'+''.join('<p class="option">'+k+'. '+E(v)+'</p>' for k,v in zip('ABCD',q['options']))+'<p>Respuesta: ______</p></div>'
def chtml(c):return f'<article class="card"><h3>{E(c["term"])} · {c["id"]}</h3><p>{E(c["definition"])}</p><p class="example"><b>Ejemplo.</b> {E(c["example"])}</p><p><b>Aplica en tu cuaderno.</b> {E(c["practice"])}</p><small>TE 1M: {E(c["source"]["1M"] or "—")} · TE 2M: {E(c["source"]["2M"] or "—")} · páginas impresas.</small></article>'
def doc(title,body,plan=False):return f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><style>{css}</style></head><body{chr(32)+"class="+chr(34)+"plan"+chr(34) if plan else ""}>{body}</body></html>'
css+='\n.visual-print{display:block;width:100%;height:auto;max-height:129mm;object-fit:contain;margin:10px 0}.visual-notes{font:12px/1.4 Inter,sans-serif}.visual-notes li{margin:5px 0}.visual-task{font:12px/1.5 Inter,sans-serif;border:1px solid #555;padding:9px 12px;margin-top:10px}.visual-example{font:12px/1.5 Inter,sans-serif;border-left:3px solid #555;padding-left:10px}\n'
for l in D['lessons']:
    n=l['n'];pages=[]
    first=header.replace('[Título de la guía]',E(l['title'])).replace('[Objetivo de la clase, en infinitivo]',E(l['objective'])).replace('[Habilidades que se trabajan]','Interpretar, aplicar, justificar y evaluar con evidencia.')
    first=first.replace('class="value write-in"></td><td class="label-sm">Fecha','class="value write-in">II</td><td class="label-sm">Fecha').replace('<td class="value write-in" colspan="2"></td></tr>','<td class="value write-in" colspan="2">Práctica formativa</td></tr>')
    first+='''<section class="instructions"><strong>INSTRUCCIONES</strong><p>1. Observen las imágenes y lean los ejemplos resueltos. 2. Apliquen cada explicación en el cuaderno, según su consigna. 3. Respondan individualmente las alternativas y tareas escritas de esta guía. 4. Revisen una respuesta con su pareja y corrijan antes de entregar.</p></section>'''
    first+=f'<div class="content"><h2>Antes de comenzar</h2><p>{E(l["activation"])}</p>{lines(3)}<div class="rules"><b>Normas de trabajo</b><p>Escuchen y fundamenten sus ideas con respeto. Cuiden los materiales y la procedencia de la información. No se permite el uso de celular.</p></div><h2>Una pregunta para toda la clase</h2><p>{E(l["central"])}</p><p class="source">Fecha programada: {E(l["date"])}. Textos y ejercicios originales de CEST. Referencias conceptuales: textos escolares MINEDUC de 1.º y 2.º medio. No es una prueba oficial PAES.</p></div>'
    pages.append(first)
    core=[next(c for c in D['cards'] if c['id']==id) for id in l['core']]
    m=l['model']
    for v in V[str(n)]:
        pages.append(f'<h2>Observamos y comprendemos · {E(v["title"])}</h2><img class="visual-print" src="../assets/ia/{v["id"]}.webp" alt="{E(v["alt"])}"><ul class="visual-notes">'+''.join('<li>'+E(t)+'</li>' for t in v['explain'])+f'</ul><p class="visual-example"><b>Ejemplo resuelto.</b> {E(v["example"])}</p><div class="visual-task"><b>Ahora aplica.</b> {E(v["apply"])}</div><p class="source">Escribe una idea o ejemplo aquí y desarrolla la respuesta en tu cuaderno.</p>'+lines(3))
    for start in range(0,12,4):pages.append('<h2>Aplicamos · Definiciones y oraciones</h2><p class="content">Elige la opción que explica mejor el ejemplo. Puedes consultar las fichas.</p>'+''.join(qhtml(q) for q in l['micro'][start:start+4]))
    for t in l['texts']:
        # Una lectura y sus preguntas forman un bloque contiguo, antes del siguiente texto.
        pages.append(f'<h2>Leemos · {E(t["title"])}</h2><p class="source">{E(t["genre"])}</p><article class="reading">'+''.join('<p>'+E(p)+'</p>' for p in t['paragraphs'])+'</article><p class="source">'+E(t['source'])+'</p><p class="content">Subraya un indicio relevante y escribe qué permite comprender.</p>'+lines(3))
        pages.append(f'<h2>Aplicamos · {E(t["title"])}</h2>'+''.join(qhtml(q) for q in t['questions'])+'<p class="content">Elige una respuesta y justifícala con una pista de la lectura.</p>'+lines(3))
    for w in l['writing']:pages.append(f'<h2>Escribimos y revisamos · Tarea {w["id"][1:]}</h2><p class="content">{E(w["prompt"])}</p>{lines(14)}<p class="content"><b>Revisión en pareja.</b> ¿El ejemplo cumple la definición? ¿La evidencia respalda la explicación? Señala una mejora y corrige tu respuesta.</p>{lines(3)}')
    pages.append('<h2>Cierre · Explicar qué cambió</h2><p class="content">Revisa las alternativas y las tareas escritas antes de entregar. Responde individualmente.</p>'+''.join('<p class="content"><b>'+E(r['prompt'])+'</b></p>'+lines(5) for r in l['reflection'])+'<p class="source">Para continuar el repaso hasta el 9 de diciembre: estudiacest.com/paes/nm2/fichas.html. Escoge contenidos que te cueste aplicar y responde sus consignas en el cuaderno.</p>')
    sheets=[]
    for i,p in enumerate(pages,1):sheets.append(f'<article class="sheet" data-page="{i}">{p}<footer class="footer"><span>EDUCAR EVANGELIZANDO Y EVANGELIZAR EDUCANDO, MEDIANTE UNA FORMACIÓN CONTINUA Y DE CALIDAD</span><span class="page-number">Página {i} de {len(pages)}</span></footer></article>')
    (OUT/f'guia-{n}.html').write_text(doc(l['title'],f'<nav class="print-tools"><a href="../">Volver a las clases</a> · <a href="guia-{n}.pdf">Descargar PDF</a> · <button onclick="print()">Imprimir</button></nav>'+''.join(sheets)),encoding='utf-8')
    stages=[('0–5','Activar','Proyectar la pregunta inicial y recuperar dos respuestas diferentes.','Pensar, escribir una razón en el cuaderno y compartir en pareja.','La razón revela una idea previa que se retomará en el cierre.'),('5–8','Acordar y orientar','Presentar normas y objetivo en pantallas distintas.','Preparar materiales y explicar qué tendrán que justificar.','Reconocen qué producto evidencia el verbo del objetivo.'),('8–23','Explicar y modelar','Usar infografía, fichas y ejemplo resuelto; verbalizar observación, relación y conclusión.','Comparar definición y ejemplo; probar una consigna oralmente.','Nombran un indicio y explican su relación con el concepto.'),('23–38','Aplicar en frases','Revisar 12 decisiones; pedir una explicación antes de dar la clave.','Responder individualmente y contrastar una decisión con su pareja.','La explicación distingue un concepto de su distractor cercano.'),('38–63','Transferir a lecturas','Acompañar las tres lecturas; preguntar dónde está la pista y qué permite concluir.','Leer, responder 12 preguntas y justificar oralmente una decisión.','Diferencian lo explícito, la inferencia y una afirmación sin respaldo.'),('63–83','Escribir y revisar','Observar las tres tareas y orientar la corrección con la pauta privada.','Producir respuestas, intercambiar una y mejorarla con evidencia.','La revisión cambia una oración o explicación concreta del borrador.'),('83–90','Sistematizar y cerrar','Contrastar una idea inicial con la final y recoger el ticket de reflexión.','Explicar un aprendizaje con ejemplo, evidencia y una mejora.','El ticket permite decidir el repaso siguiente.')]
    roadmap=f'<section class="roadmap"><p>ESTUDIA CEST · HOJA DE RUTA DOCENTE · 2.º A y B HC</p><h1>Clase {n} · {E(l["title"])}</h1><p><b>Fecha:</b> {E(l["date"])} · <b>Duración estimada:</b> 90 minutos</p><p><b>Objetivo:</b> {E(l["objective"])}</p><p><b>Pregunta central:</b> {E(l["central"])}</p><table><thead><tr><th>Minutos</th><th>Momento</th><th>Docente</th><th>Estudiantes</th><th>Qué observar</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(v)+'</td>' for v in row)+'</tr>' for row in stages)+'</tbody></table><p><b>Recursos:</b> proyector, fichas e infografía; guía impresa o computador con cuenta. Cuaderno y lápiz. Presentación de tres pantallas iniciales separadas.</p><p><b>Producto:</b> 24 alternativas, tres tareas escritas revisadas y ticket. La biblioteca de 237 fichas es de consulta y repaso; no se exige completar las 237 consignas en cuatro clases.</p></section>'
    conceptnames=', '.join(c['term'] for c in core)
    detail=f'<h2>Contenidos, procedimiento y disposición</h2><p><b>Conceptual:</b> {E(conceptnames)}. Enseñar definición, ejemplo y relación con el sentido; no reducir la clase a nombrarlos.</p><p><b>Procedimental:</b> observar indicios, contrastar con una definición, formular una interpretación, localizar evidencia y explicar su alcance. Modelar el procedimiento antes de pedir transferencia.</p><p><b>Actitudinal:</b> escuchar otra lectura, fundamentar desacuerdos, reconocer límites y corregir el propio borrador. Observar turnos y cambios concretos tras la revisión.</p><h2>Correspondencia curricular y fuentes</h2><p>{E(", ".join(l["oa"]))}. Los contenidos de 1.º medio funcionan como conocimientos previos para los OA de 2.º medio; el listado conceptual no equivale a una enumeración literal de OA.</p><p>{E(l["source"])}</p><p>Catálogo completo y trazabilidad: <a href="../COBERTURA.md">matriz de 237 entradas</a>. Definiciones, ejemplos, lecturas, preguntas e infografías: elaboración original CEST, informada por los textos y guías docentes; no reproducción de sus actividades.</p><h2>Mediación durante el modelamiento</h2><p><b>Ejemplo:</b> {E(m["sample"])}</p><p><b>Hacer visible:</b> {E(m["notice"])} {E(m["reasoning"])}</p><p><b>Conclusión fundamentada:</b> {E(m["conclusion"])}</p><p><b>Comprobación:</b> {E(m["check"])} Solicitar una razón y distinguir lo que el fragmento dice de lo que habría que verificar.</p><h2>Monitorear para intervenir</h2><p>Si confunden dos conceptos, pedir que indiquen el rasgo que los diferencia y vuelvan a una oración de la ficha. Si nombran una figura sin explicar su efecto, preguntar qué relación crea y qué cambia en este contexto. Si responden por conocimiento externo, pedir una pista del texto y revisar hasta dónde permite concluir.</p><p>En la escritura, revisar definición, ejemplo y evidencia. La pauta privada del panel indica respuestas admisibles y apoyos específicos; aceptar formulaciones distintas que estén justificadas. Pedir una modificación concreta antes de entregar, no solo un visto bueno.</p><h2>Revisión y decisiones</h2><p>Registrar, por estudiante, si reconoce el contenido, lo aplica en un ejemplo y explica su efecto con evidencia. Son observaciones cualitativas; no hay ponderación automática de escritura ni conversión a nota. Las alternativas se corrigen en servidor y la pauta se publica por curso desde el panel docente.</p><p>Si la alternativa es correcta pero falta explicación, pedir una justificación breve. Si la definición es correcta y la transferencia falla, volver al texto y contrastar dos opciones. Si persiste la dificultad, seleccionar una ficha y una oración nuevas para la sesión siguiente.</p><h2>Apoyos y recorrido acompañado</h2><p>Ofrecer lectura en voz alta y fragmentación del texto sin anticipar la respuesta. El recorrido acompañado presenta un estímulo breve, audio y seis preguntas de una en una, sin reloj. Se asigna por cuenta y conserva evidencia separada. Su pauta se consulta en el mismo panel.</p><h2>Carga real y repaso entre sesiones</h2><p>{l["load"]["readingWords"]} palabras de lectura regular, 24 decisiones cerradas, tres tareas escritas y tres reflexiones. Los tiempos son estimaciones a calibrar con el curso; no hay espera ni límite de tiempo automático. Si el desarrollo requiere más mediación, registrar qué se trabajó y continuar el resto antes del 9 de diciembre. No declarar dominio de las 237 entradas por haberlas puesto a disposición.</p><p>Entre sesiones, seleccionar de cuatro a seis fichas según los errores observados. Cada estudiante explica una definición con sus palabras, crea una oración, la aplica en un fragmento y revisa con el ejemplo. En la clase siguiente, recuperar dos aplicaciones y corregir una dificultad compartida.</p><h2>Enlaces de trabajo</h2><p><a href="../clase.html?clase={n}">Clase regular</a> · <a href="../guiada.html?clase={n}">Vista del recorrido acompañado</a> · <a href="../presentacion.html?clase={n}">Presentación</a> · <a href="guia-{n}.pdf">Guía PDF</a> · <a href="../docente.html">Panel y pauta privada</a></p><p>Referencias curriculares verificadas: <a href="https://www.curriculumnacional.cl/614/w3-article-80975.html">OA 03</a>, <a href="https://www.curriculumnacional.cl/614/w3-article-80976.html">OA 04</a>, <a href="https://www.curriculumnacional.cl/614/w3-article-80977.html">OA 05</a>, <a href="https://www.curriculumnacional.cl/614/w3-article-79933.html">argumentación y medios</a>, <a href="https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/lengua-literatura/2-medio/le2m-oa-14">OA 14</a> y <a href="https://www.curriculumnacional.cl/curriculum/7o-basico-2o-medio/lengua-literatura/2-medio/le2m-oa-24">OA 24</a>.</p>'
    visual_detail='<h2>Imágenes, explicación y aplicación</h2><p>Proyectar cada lámina por separado. Pedir primero que describan la pista visual; después relacionarla con la definición y el ejemplo resuelto. Las imágenes son ilustraciones didácticas originales, no evidencia documental de hechos reales.</p>'
    for i,v in enumerate(V[str(n)]):
        visual_detail+=f'<h3>Diapositivas {4+i*2}–{5+i*2} · {E(v["title"])}</h3><p><b>Recurso:</b> <a href="../assets/ia/{v["id"]}.webp">lámina ilustrada</a> · Guía, página {i+2}.</p><p><b>Ejemplo que se explica:</b> {E(v["example"])}</p><p><b>Aplicación:</b> {E(v["apply"])}</p><p><b>Observar e intervenir:</b> comprobar que la producción cumple el rasgo del concepto que se acaba de explicar. Pedir que subrayen ese rasgo, lo relacionen con la definición y corrijan una parte si no coincide. No aceptar solo el nombre del recurso: solicitar la pista y su efecto en el caso creado.</p>'
    roadmap=roadmap.replace('Usar infografía, fichas y ejemplo resuelto; verbalizar observación, relación y conclusión.','Proyectar láminas y aplicaciones, diapositivas 4–'+str(3+len(V[str(n)])*2)+'. Comparar pistas, definición y ejemplo.').replace('proyector, fichas e infografía;','proyector, láminas ilustradas;')
    detail=detail.replace('Enseñar definición, ejemplo y relación con el sentido; no reducir la clase a nombrarlos.','Las láminas enseñan los conceptos seleccionados con definición, ejemplo y aplicación. El resto del catálogo se consulta y repasa según las dificultades observadas; no se afirma enseñar todo el listado en una sesión.')
    (OUT/f'planificacion-{n}.html').write_text(doc('Planificación · '+l['title'],roadmap+visual_detail+detail,True),encoding='utf-8')
    print(f'Clase {n}: {len(pages)} páginas de guía; hoja de ruta y mediación generadas.')
